import{_ as t,o as a,c as r,ae as i}from"./chunks/framework.B2ul6ABY.js";const h=JSON.parse('{"title":"Top-Level Planner MCP Redesign Plan","description":"","frontmatter":{},"headers":[],"relativePath":"top-level-planner-mcp-redesign-plan.md","filePath":"top-level-planner-mcp-redesign-plan.md"}'),n={name:"top-level-planner-mcp-redesign-plan.md"};function l(o,e,c,s,d,u){return a(),r("div",null,[...e[0]||(e[0]=[i('<blockquote><p><strong>Historical/Audit Artifact — Not Current Operator Instructions</strong><br> This page records a redesign plan from an earlier stage. It is not authoritative for current Saivage v3 behavior unless a current active doc explicitly revalidates it against current source and tests.</p></blockquote><h1 id="top-level-planner-mcp-redesign-plan" tabindex="-1">Top-Level Planner MCP Redesign Plan <a class="header-anchor" href="#top-level-planner-mcp-redesign-plan" aria-label="Permalink to &quot;Top-Level Planner MCP Redesign Plan&quot;">​</a></h1><p>Status note: this is the current recovery work plan, not an authoritative product spec. Existing specs, historical plans, and docs may be obsolete; validate every design decision against current source code, live runtime behavior, and the user&#39;s latest instructions before updating broader documentation.</p><h2 id="problem-statement" tabindex="-1">Problem Statement <a class="header-anchor" href="#problem-statement" aria-label="Permalink to &quot;Problem Statement&quot;">​</a></h2><p>The current Saivage v3 runtime can execute a short sequence of leaf cards, but the control model is still too shallow. After a planner creates terminal cards and those cards run, the system should return control to a strategic planner attached to the project or goal, inspect the current project state, decide whether the objective is complete, and then create or dispatch the next layer of work. That behavior must be an application-level invariant, not a prompt convention.</p><p>The live the target project run exposed three related issues:</p><ol><li>The runtime planner loop is goal-local and card-queue driven. It can re-enter the goal planner after <code>executeReadyCards</code>, but the control boundary is implicit and depends on executor result parsing and queue exhaustion.</li><li>Executors can successfully modify files through tools and still fail the runtime because the final structured JSON result is brittle. That traps the system in retry/fallback churn and delays or prevents strategic replanning.</li><li>The UI shows card status but does not make generated files first-class evidence that an operator can inspect directly from a card.</li></ol><h2 id="architectural-direction" tabindex="-1">Architectural Direction <a class="header-anchor" href="#architectural-direction" aria-label="Permalink to &quot;Architectural Direction&quot;">​</a></h2><p>Restore the stronger Saivage v2 idea: planners should call explicit control-plane tools for subgoal and task execution through an MCP-style dispatch surface. The planner should not merely emit static cards and hope the runtime scheduler infers the correct next move. Instead, the runtime should expose durable operations such as:</p><ul><li><code>plan_get_project_state</code></li><li><code>plan_get_goal_state</code></li><li><code>plan_create_goal</code></li><li><code>plan_create_task</code></li><li><code>dispatch_goal</code></li><li><code>dispatch_card</code></li><li><code>wait_for_dispatch</code></li><li><code>inspect_artifacts</code></li><li><code>request_review</code></li></ul><p>These tools should be backed by the same card store and runtime state, but they should give the planner an observable, transactional loop: inspect, create, dispatch, wait, inspect evidence, then decide whether to continue, finish, or escalate.</p><h2 id="required-stages" tabindex="-1">Required Stages <a class="header-anchor" href="#required-stages" aria-label="Permalink to &quot;Required Stages&quot;">​</a></h2><h3 id="stage-1-diagnose-current-control-flow" tabindex="-1">Stage 1: Diagnose Current Control Flow <a class="header-anchor" href="#stage-1-diagnose-current-control-flow" aria-label="Permalink to &quot;Stage 1: Diagnose Current Control Flow&quot;">​</a></h3><ul><li>Trace <code>Runtime.dispatchGoal</code>, <code>runGoal</code>, <code>executeReadyCards</code>, planner result application, reviewer invocation, and continuous improvement.</li><li>Document the exact conditions under which control returns to the goal planner.</li><li>Identify where project-level planning is absent or only used for backlog auto-dispatch.</li><li>Add focused tests that reproduce a goal with incomplete acceptance after initial terminal cards finish.</li></ul><h3 id="stage-2-define-planner-control-mcp-contract" tabindex="-1">Stage 2: Define Planner Control MCP Contract <a class="header-anchor" href="#stage-2-define-planner-control-mcp-contract" aria-label="Permalink to &quot;Stage 2: Define Planner Control MCP Contract&quot;">​</a></h3><ul><li>Design an in-process MCP/control service for card planning and dispatch.</li><li>Specify tool schemas, authorization by role, state transitions, idempotency, and error semantics.</li><li>Decide which planner levels may call which tools: project planner, goal planner, reviewer, and analyst.</li><li>Include a project-level planning loop so the project card can own strategic expansion across goals.</li></ul><h3 id="stage-3-refactor-runtime-around-explicit-dispatch-tools" tabindex="-1">Stage 3: Refactor Runtime Around Explicit Dispatch Tools <a class="header-anchor" href="#stage-3-refactor-runtime-around-explicit-dispatch-tools" aria-label="Permalink to &quot;Stage 3: Refactor Runtime Around Explicit Dispatch Tools&quot;">​</a></h3><ul><li>Replace implicit queue-only orchestration with explicit planner dispatch operations.</li><li>Preserve crash recovery and current card-store compatibility.</li><li>Ensure parent planners can suspend while dispatched subgoals/cards execute and then resume with structured results.</li><li>Prevent leaf-card completion from marking a parent goal done unless reviewer evidence proves acceptance criteria.</li></ul><h3 id="stage-4-harden-structured-result-handling" tabindex="-1">Stage 4: Harden Structured Result Handling <a class="header-anchor" href="#stage-4-harden-structured-result-handling" aria-label="Permalink to &quot;Stage 4: Harden Structured Result Handling&quot;">​</a></h3><ul><li>Make executor completion robust when tools succeeded but final JSON is malformed or incomplete.</li><li>Persist tool evidence and file write evidence as first-class execution records.</li><li>Add a recovery parser or runtime synthesis step that can produce a failed/done executor result from verified tool outcomes without losing provenance.</li><li>Remove noisy provider fallback attempts when configuration says no fallback is allowed.</li></ul><h3 id="stage-5-add-generated-file-inspection-to-the-ui" tabindex="-1">Stage 5: Add Generated File Inspection to the UI <a class="header-anchor" href="#stage-5-add-generated-file-inspection-to-the-ui" aria-label="Permalink to &quot;Stage 5: Add Generated File Inspection to the UI&quot;">​</a></h3><ul><li>Extend card API responses with generated artifact/file references.</li><li>Add card detail UI controls to open generated files directly.</li><li>Support read-only file preview for workspace-relative files with redaction and path containment.</li><li>Surface verification commands and tool evidence alongside generated files.</li></ul><h3 id="stage-6-verification-and-live-recreation" tabindex="-1">Stage 6: Verification and Live Recreation <a class="header-anchor" href="#stage-6-verification-and-live-recreation" aria-label="Permalink to &quot;Stage 6: Verification and Live Recreation&quot;">​</a></h3><ul><li>Add unit tests for project-level planner re-entry, goal-level replanning, dispatch-tool suspend/resume, and malformed executor final result recovery.</li><li>Add integration tests where an initial planner creates two leaf cards, both finish, and the parent planner creates the next stage because acceptance remains incomplete.</li><li>Run typecheck, build, docs verification, focused Jest suites, and a full Jest run.</li><li>Redeploy to the LXC service and recreate the the target project project from a clean state.</li><li>Verify through API and UI that planners continue expanding work until the project is actually complete or explicitly blocked.</li></ul><h2 id="acceptance-criteria" tabindex="-1">Acceptance Criteria <a class="header-anchor" href="#acceptance-criteria" aria-label="Permalink to &quot;Acceptance Criteria&quot;">​</a></h2><ul><li>A project or goal planner can explicitly dispatch subgoals/cards through MCP-style tools and inspect completion evidence before deciding next work.</li><li>Parent planners always regain control after dispatched work finishes, even when no ready leaf queue remains.</li><li>A parent goal cannot be marked done solely because its current child queue is empty.</li><li>Executor tool success and final JSON result handling are robust enough to avoid retry loops after useful work has already been completed.</li><li>The UI lets an operator inspect generated files and evidence directly from card details.</li><li>The live the target project recreation demonstrates multiple planner/executor/replanner cycles without manual nudging.</li></ul>',26)])])}const g=t(n,[["render",l]]);export{h as __pageData,g as default};
